package user

import (
	"context"
	"errors"
	"strings"
	"time"
)

var (
	ErrSignupEvidenceUnavailable = errors.New("user/signup-evidence-unavailable")
	ErrSignupEvidenceInvalid     = errors.New("user/signup-evidence-invalid")
	ErrSignupEvidenceConflict    = errors.New("user/signup-evidence-conflict")
)

// SignupAttributionConfig is explicit host composition. Account types come
// from the owning identity configuration; organization/seat eligibility is not
// inferred from email or roles. Configure before concurrent serving.
type SignupAttributionConfig struct {
	ProgramID              string
	IndividualAccountTypes []string
}

// SignupAttribution is private immutable account-creation context committed in
// the same document as the new account. Profile updates cannot rewrite it.
// Evidence is bounded signed context, not a login credential or proof of a paid
// subscription; its owning consumer still verifies signature and eligibility.
type SignupAttribution struct {
	ProgramID  string    `bson:"program_id" json:"-"`
	CustomerID string    `bson:"customer_id" json:"-"`
	CreatedAt  time.Time `bson:"created_at" json:"-"`
	// CreatedAtUTC preserves the exact owning-clock instant across BSON's
	// millisecond date precision. Consumers validate it against CreatedAt.
	CreatedAtUTC string             `bson:"created_at_utc" json:"-"`
	Individual   bool               `bson:"individual" json:"-"`
	Evidence     string             `bson:"evidence,omitempty" json:"-"`
	State        string             `bson:"state" json:"-"`
	Consumption  *SignupConsumption `bson:"consumption,omitempty" json:"-"`
}

// SignupConsumption records the trusted consumer's durable acceptance or
// explicit no-attribution decision, without changing the creation evidence.
type SignupConsumption struct {
	ReceiptID  string    `bson:"receipt_id" json:"-"`
	Outcome    string    `bson:"outcome" json:"-"`
	ActorID    string    `bson:"actor_id" json:"-"`
	RecordedAt time.Time `bson:"recorded_at" json:"-"`
}

// SignupEvidenceRepository is optional for existing identity integrations but
// required before enabling durable signup attribution in a host.
type SignupEvidenceRepository interface {
	GetSignupAttribution(context.Context, string, string) (SignupAttribution, error)
	PendingSignupAttributions(context.Context, string, int) ([]SignupAttribution, error)
	ConsumeSignupAttribution(context.Context, string, string, SignupConsumption) error
}

// SignupEvidencePagingRepository separates bounded discovery from consumption.
// Workers persist/reset their sweep position independently from each source's
// durable owning acceptance; late lower IDs remain visible on the next sweep.
type SignupEvidencePagingRepository interface {
	PendingSignupAttributionsAfter(context.Context, string, string, int) ([]SignupAttribution, error)
}

// WithSignupAttribution installs an explicit capture/feed capability. Creation
// remains one atomic insert; old accounts are not retroactively given evidence.
func (s *Service) WithSignupAttribution(config SignupAttributionConfig) (*Service, error) {
	if s == nil || nilUserDependency(s.UserRepository) || nilUserDependency(s.TimeProvider) {
		return nil, ErrSignupEvidenceUnavailable
	}
	if _, ok := s.UserRepository.(SignupEvidenceRepository); !ok {
		return nil, ErrSignupEvidenceUnavailable
	}
	if strings.TrimSpace(config.ProgramID) == "" || len(config.ProgramID) > 128 || len(config.IndividualAccountTypes) == 0 {
		return nil, ErrSignupEvidenceInvalid
	}
	config.IndividualAccountTypes = append([]string(nil), config.IndividualAccountTypes...)
	seen := make(map[string]bool, len(config.IndividualAccountTypes))
	for _, kind := range config.IndividualAccountTypes {
		if strings.TrimSpace(kind) == "" || len(kind) > 128 || seen[kind] {
			return nil, ErrSignupEvidenceInvalid
		}
		seen[kind] = true
	}
	s.signupAttribution = &config
	return s, nil
}
func (s *Service) captureSignup(user *UniversalUser, evidence string) error {
	if s.signupAttribution == nil {
		return nil
	}
	if user == nil || user.ID == "" || user.Metadata == nil || len(evidence) > 2048 {
		return ErrSignupEvidenceInvalid
	}
	at, err := time.Parse(time.RFC3339Nano, user.Metadata.CreatedAt)
	if err != nil {
		// Existing owning clocks format UTC without a zone. This field was just
		// generated by SetInitialState, never read from a browser or old account.
		at, err = time.ParseInLocation(DefaultTimeFormatRFC3339NanoUTC, user.Metadata.CreatedAt, time.UTC)
	}
	if err != nil || at.IsZero() {
		return ErrSignupEvidenceInvalid
	}
	individual := false
	for _, kind := range s.signupAttribution.IndividualAccountTypes {
		if user.Type == kind {
			individual = true
			break
		}
	}
	user.SignupAttribution = &SignupAttribution{ProgramID: s.signupAttribution.ProgramID, CustomerID: user.ID, CreatedAt: at.UTC(), CreatedAtUTC: at.UTC().Format(time.RFC3339Nano), Individual: individual, Evidence: evidence, State: "pending"}
	return nil
}
func (s *Service) signupPort(ctx context.Context) (SignupEvidenceRepository, error) {
	if ctx == nil {
		return nil, ErrSignupEvidenceInvalid
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if s == nil || s.signupAttribution == nil || nilUserDependency(s.UserRepository) || nilUserDependency(s.TimeProvider) {
		return nil, ErrSignupEvidenceUnavailable
	}
	port, ok := s.UserRepository.(SignupEvidenceRepository)
	if !ok {
		return nil, ErrSignupEvidenceUnavailable
	}
	return port, nil
}

// GetSignupAttribution exposes private immutable creation evidence only as an
// in-process owning-service capability. No public HTTP route is registered.
func (s *Service) GetSignupAttribution(ctx context.Context, customer string) (SignupAttribution, error) {
	port, err := s.signupPort(ctx)
	if err != nil {
		return SignupAttribution{}, err
	}
	if strings.TrimSpace(customer) == "" || len(customer) > 256 {
		return SignupAttribution{}, ErrSignupEvidenceInvalid
	}
	return port.GetSignupAttribution(ctx, s.signupAttribution.ProgramID, customer)
}

// PendingSignupAttributions has no global cursor: late-created IDs and an
// unresolved earlier account cannot be skipped by a later acknowledgement.
func (s *Service) PendingSignupAttributions(ctx context.Context, limit int) ([]SignupAttribution, error) {
	port, err := s.signupPort(ctx)
	if err != nil {
		return nil, err
	}
	if limit < 1 || limit > 200 {
		return nil, ErrSignupEvidenceInvalid
	}
	return port.PendingSignupAttributions(ctx, s.signupAttribution.ProgramID, limit)
}
func (s *Service) ConsumeSignupAttribution(ctx context.Context, customer string, consumption SignupConsumption) error {
	port, err := s.signupPort(ctx)
	if err != nil {
		return err
	}
	if strings.TrimSpace(customer) == "" || len(customer) > 256 || strings.TrimSpace(consumption.ActorID) == "" || len(consumption.ActorID) > 256 || strings.TrimSpace(consumption.ReceiptID) == "" || len(consumption.ReceiptID) > 256 {
		return ErrSignupEvidenceInvalid
	}
	switch consumption.Outcome {
	case "attributed", "no_evidence", "ineligible", "quarantined":
	default:
		return ErrSignupEvidenceInvalid
	}
	consumption.RecordedAt = s.TimeProvider.Now().UTC()
	return port.ConsumeSignupAttribution(ctx, s.signupAttribution.ProgramID, customer, consumption)
}

// PendingSignupAttributionsAfter supports a persisted bounded discovery sweep.
// Advancing this position does not consume any creation evidence.
func (s *Service) PendingSignupAttributionsAfter(ctx context.Context, afterCustomer string, limit int) ([]SignupAttribution, error) {
	port, err := s.signupPort(ctx)
	if err != nil {
		return nil, err
	}
	if afterCustomer != strings.TrimSpace(afterCustomer) || len(afterCustomer) > 256 || strings.ContainsAny(afterCustomer, "\r\n\x00") || limit < 1 || limit > 200 {
		return nil, ErrSignupEvidenceInvalid
	}
	paging, ok := port.(SignupEvidencePagingRepository)
	if !ok || nilUserDependency(paging) {
		return nil, ErrSignupEvidenceUnavailable
	}
	return paging.PendingSignupAttributionsAfter(ctx, s.signupAttribution.ProgramID, afterCustomer, limit)
}
